#!/bin/bash

# Required parameters:
# @raycast.schemaVersion 1
# @raycast.title Striple State
# @raycast.mode fullOutput
# @raycast.packageName Striple

# Optional parameters:
# @raycast.icon ℹ️
# @raycast.description Show displays, columns and windows. Runs: striple state

# Generated by generate.sh. Do not edit: change generate.sh and run it again.

cmd="state"

find_cli() {
  command -v striple 2>/dev/null && return
  # Raycast does not load your shell profile, so also look in the usual places.
  for p in "$HOME/.local/bin/striple" /Applications/Striple.app/Contents/Helpers/striple; do
    if [ -x "$p" ]; then echo "$p"; return; fi
  done
}

cli="$(find_cli)"
if [ -z "$cli" ]; then
  echo "The striple command-line tool is not installed. Run 'make install' in the Striple source folder."
  exit 1
fi
"$cli" "$cmd" 2>&1
